import{_ as t,o,c as a,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"Plan — FR 3.5.9: Complete Media Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/04-media-package-campaign/3-5-9-complete-media-campaign/plan.md","filePath":"feature/srs/04-media-package-campaign/3-5-9-complete-media-campaign/plan.md"}'),n={name:"feature/srs/04-media-package-campaign/3-5-9-complete-media-campaign/plan.md"};function d(r,e,s,i,l,p){return o(),a("div",null,[...e[0]||(e[0]=[c('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-5-9-complete-media-campaign" tabindex="-1">Plan — FR 3.5.9: Complete Media Campaign <a class="header-anchor" href="#plan-—-fr-3-5-9-complete-media-campaign" aria-label="Permalink to &quot;Plan — FR 3.5.9: Complete Media Campaign&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> for canonical roles <code>Owner, Manager</code> enforcing <code>BR-30</code>.</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>GatewayConfig.java</code> (JWT-protected <code>/api/v1/**</code> plus public guest share <code>/api/v1/public/media-packages/**</code>), <code>JwtAuthFilterGatewayFilterFactory.java</code></td></tr><tr><td style="text-align:left;"><strong>Controllers</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>CampaignClosureController.preview() / cancel(), WorkspaceCampaignController.complete()</code></td></tr><tr><td style="text-align:left;"><strong>Services</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>CampaignDeploymentService, CampaignClosureStore, ContentRequestStore</code></td></tr><tr><td style="text-align:left;"><strong>Repositories / Stores</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;">MediaCampaignRepository, TaskMongoRepository, ContentRequestStore</td></tr><tr><td style="text-align:left;"><strong>Security / ACL</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>RequireRoleAspect.java</code>, <code>WorkspaceAccessService.java</code>, <code>WorkspaceIsolationHelper.java</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/campaign/{index,page}.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>src/screens/more/CampaignDetailScreen.tsx</code>, <code>src/services/campaignService.ts</code></td></tr></tbody></table><h2 id="_2-hybrid-postgresql-mongodb-data-model" tabindex="-1">2. Hybrid PostgreSQL &amp; MongoDB Data Model <a class="header-anchor" href="#_2-hybrid-postgresql-mongodb-data-model" aria-label="Permalink to &quot;2. Hybrid PostgreSQL &amp; MongoDB Data Model&quot;">​</a></h2><ul><li><strong>Data Stores:</strong> PostgreSQL <code>media_campaigns</code> (<code>status = COMPLETED</code>, <code>completed_at</code>); MongoDB <code>tasks</code>, <code>content_requests</code>.</li><li><strong>Schema &amp; Invariant Design:</strong><ul><li>Runs a pre-closure audit (<code>GET /completion-check</code>) listing unfinished Tasks (<code>BACKLOG</code>, <code>TODO</code>, <code>IN_PROGRESS</code>, <code>IN_REVIEW</code>), lets <code>Owner</code>/<code>Manager</code> bulk-cancel unstarted/abandoned Tasks (<code>POST /tasks/cancel</code> cleaning <code>reviewStep</code>/<code>lastSubmission</code> via CAS), transitions the <code>IN_PROGRESS</code> Campaign to <code>COMPLETED</code> (<code>POST /complete</code>, <code>BR-30</code>), and automatically cancels remaining <code>PENDING</code> Content Requests with audit history.</li><li><strong>PostgreSQL Constraints &amp; Indexes:</strong><ul><li><code>media_packages(agency_id, is_available)</code> + unique <code>share_token</code> index for Agency catalogue and O(1) public share resolution.</li><li><code>workspace_media_packages</code>: <code>UNIQUE(workspace_id)</code> agreement row with <code>final_terms</code> JSONB snapshot and <code>terms_version</code>.</li><li><code>package_negotiation_events</code>: append-only audit table with <code>UNIQUE(workspace_media_package_id, terms_version)</code> and DB immutability trigger.</li><li><code>media_campaigns</code>: <code>UNIQUE(workspace_media_package_id)</code>, <code>work_items</code> JSONB, <code>content_version</code>, <code>campaign_versions</code>, <code>campaign_review_events</code>, <code>campaign_deployments</code>, and <code>campaign_collaborators</code> (<code>UNIQUE(media_campaign_id, collaborator_id)</code>).</li></ul></li><li><strong>MongoDB Collections &amp; Indexes (<code>tasks</code>, <code>content_requests</code>):</strong><ul><li><code>tasks</code>: scoped by <code>workspaceId</code>, indexed on <code>(workspaceId, campaignId)</code> and partial unique <code>(workspaceId, sourceType, sourceRefId)</code> so package sync and Content Request acceptance never create duplicate Tasks on retry.</li><li><code>content_requests</code>: indexed on <code>(workspaceId, status, createdAt)</code> with atomic <code>version</code> field for CAS transitions.</li></ul></li></ul></li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Client Action:</strong> Actor (<code>Owner, Manager</code>) triggers <strong>Complete Media Campaign</strong> on <code>src/pages/campaign/{index,page}.tsx</code> (Web) or <code>src/screens/more/CampaignDetailScreen.tsx</code>, <code>src/services/campaignService.ts</code> (Mobile), passing current entity version (<code>expectedTermsVersion</code> / <code>expectedVersion</code>) where mutating state.</li><li><strong>Gateway &amp; Tenant Verification:</strong> API Gateway validates JWT (except public guest share route in <code>3.5.2</code>); Business Service re-verifies active Agency ownership or Workspace membership in PostgreSQL.</li><li><strong>Rule &amp; Concurrency Check:</strong> <code>CampaignDeploymentService, CampaignClosureStore, ContentRequestStore</code> acquires agreement/row lock or evaluates MongoDB CAS filter, validates <code>BR-30</code> (state transition, deliverable schema, Workspace timezone deadline window), and rejects stale/illegal requests with <code>403 FORBIDDEN</code>, <code>404 CAMPAIGN_NOT_FOUND</code>, <code>409 INVALID_CAMPAIGN_STATE</code> / <code>OPEN_TASKS_REMAINING</code> (<code>BR-30</code>).</li><li><strong>Persistence &amp; Cross-Store Coordination:</strong> Commits PostgreSQL/MongoDB state updates atomically per store boundary (using explicit deployment/preparation status tracking and idempotent retry keys where PostgreSQL Campaign plans materialize MongoDB Tasks).</li><li><strong>UI Refresh:</strong> Returns <code>ApiResponse&lt;T&gt;</code>; client invalidates relevant query keys (<code>media-package</code>, <code>campaigns</code>, <code>tasks</code>, <code>content-requests</code>) and updates UI without losing unsaved draft text on <code>409</code>.</li></ol><h2 id="_4-security-concurrency-failure-recovery" tabindex="-1">4. Security, Concurrency &amp; Failure Recovery <a class="header-anchor" href="#_4-security-concurrency-failure-recovery" aria-label="Permalink to &quot;4. Security, Concurrency &amp; Failure Recovery&quot;">​</a></h2><ul><li><strong>Strict Public vs Internal Separation:</strong> Guest package share links (<code>GET /api/v1/public/media-packages/{token}</code>) project only sanitized <code>PublicMediaPackageResponse</code> fields and never expose <code>workspaceId</code>, <code>ClientProfile</code>, Campaign tasks, or comments.</li><li><strong>Idempotent Retry Semantics:</strong> Package preparation (<code>/media-package/preparation/retry</code>), Campaign deployment (<code>/deploy</code>), and Content Request acceptance (<code>/accept</code>) use deterministic source keys so network retries converge to the exact same Campaign/Task records.</li><li><strong>Conflict Safety:</strong> <code>409</code> responses never auto-retry over newer versions; the user inspects updated terms/plan before confirming again.</li></ul><h2 id="_5-cross-references" tabindex="-1">5. Cross-References <a class="header-anchor" href="#_5-cross-references" aria-label="Permalink to &quot;5. Cross-References&quot;">​</a></h2><ul><li><strong>Lifecycle Artefacts:</strong> <a href="./spec.html">spec.md</a> · <a href="./task.html">task.md</a> · <a href="./test.html">test.md</a></li><li><strong>BA &amp; Module References:</strong> <a href="./../../../../ba/04-media-package-campaign.html">04-media-package-campaign.md</a> · <a href="./../../../../ba/12-state-machines.html">12-state-machines.md</a> · <a href="./../../../modules/README.html">Module Specs Index</a></li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.5.9</code> — Complete Media Campaign</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/campaigns/{campaignId}/completion-check · POST /tasks/cancel · POST /complete</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Owner, Manager</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>CampaignClosureController.preview() / cancel(), WorkspaceCampaignController.complete()</code> -&gt; <code>CampaignDeploymentService, CampaignClosureStore, ContentRequestStore</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>media_campaigns</code> (<code>status = COMPLETED</code>, <code>completed_at</code>); MongoDB <code>tasks</code>, <code>content_requests</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-30</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>403 FORBIDDEN</code>, <code>404 CAMPAIGN_NOT_FOUND</code>, <code>409 INVALID_CAMPAIGN_STATE</code> / <code>OPEN_TASKS_REMAINING</code> (<code>BR-30</code>)</td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/campaign/{index,page}.tsx</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>src/screens/more/CampaignDetailScreen.tsx</code>, <code>src/services/campaignService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>campaign.complete.* / campaign.closure.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/04-media-package-campaign.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',17)])])}const u=t(n,[["render",d]]);export{m as __pageData,u as default};
